//! SCAN.POLY.SURF.STITCH acceptance tests. Expected meshes and reports are in
//! `fixtures/scan/poly/*.stitch.txt`, written by the independent Python reference
//! `fixtures/scan/poly/make_stitch_fixtures.py` (from the Python FAN reference's fans); nothing
//! here was generated by running this crate. The sphere (AC-1) is too large for the reference:
//! its points are rebuilt from the generator in `sphere_points.txt` and checked against the
//! reference's samples bit for bit, and its expected properties (closed, manifold, outward,
//! one component, Euler characteristic 2) are hand-labelled from the spec.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::collections::BTreeMap;

use fid_geo_types::{digest_mesh, AttributeSet, FrameRef, Mesh, PointBuffer, PointCloud};
use fid_scan_poly::{
    fans, reconstruct_in_memory, stitch, Fan, FanStatus, PolyError, PrepParams, PrepVertex, ReconParams, RejectReason,
    Stitched, VertexSet, VertexStatus,
};

const FRAME: FrameRef = FrameRef::from_bytes([7; 16]);

fn read(name: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/poly/{name}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

fn f(s: &str) -> f64 {
    s.parse().unwrap()
}

fn u(s: &str) -> u64 {
    s.parse().unwrap()
}

fn vertex(source: u64, position: [f64; 3], normal: [f64; 3]) -> PrepVertex {
    PrepVertex { source, cell: [0; 3], position, normal, displacement_m: 0.0, status: VertexStatus::Unmoved }
}

fn set(vertices: Vec<PrepVertex>) -> VertexSet {
    VertexSet { vertices, h: 1e-3, smoothing: false, max_displacement_m: 0.0 }
}

fn status(s: &str) -> FanStatus {
    match s.split_once(':') {
        Some(("hidden", by)) => FanStatus::Hidden { by: u(by) },
        _ => match s {
            "ok" => FanStatus::Ok,
            "no_neighbours" => FanStatus::NoNeighbours,
            "degenerate" => FanStatus::Degenerate,
            "all_edges_long" => FanStatus::AllEdgesLong,
            other => panic!("status {other}"),
        },
    }
}

/// Fixture lines without comments.
struct Lines<'a>(std::iter::Peekable<Box<dyn Iterator<Item = &'a str> + 'a>>);

impl<'a> Lines<'a> {
    fn new(text: &'a str) -> Lines<'a> {
        let it: Box<dyn Iterator<Item = &'a str> + 'a> = Box::new(text.lines().filter(|l| !l.starts_with('#')));
        Lines(it.peekable())
    }
    fn next(&mut self) -> &'a str {
        self.0.next().unwrap()
    }
    fn field(&mut self, key: &str) -> &'a str {
        let l = self.next();
        l.strip_prefix(key).and_then(|r| r.strip_prefix(' ')).unwrap_or_else(|| panic!("expected {key}: {l}"))
    }
    fn count(&mut self, key: &str) -> usize {
        self.field(key).parse().unwrap()
    }
}

/// Vertices (`source x y z nx ny nz tag`) then fans (`centre ; status ; [neighbours ;] j:k ...`).
fn vertices_and_fans(l: &mut Lines<'_>) -> (VertexSet, Vec<Fan>) {
    let n = l.count("vertices");
    let mut vs = Vec::new();
    for _ in 0..n {
        let t: Vec<&str> = l.next().split_whitespace().collect();
        vs.push(vertex(u(t[0]), [f(t[1]), f(t[2]), f(t[3])], [f(t[4]), f(t[5]), f(t[6])]));
    }
    let m = l.count("fans");
    let mut out = Vec::new();
    for _ in 0..m {
        let parts: Vec<&str> = l.next().split(';').map(str::trim).collect();
        let centre = u(parts[0]);
        let tris = parts.last().unwrap();
        let triangles: Vec<[u64; 3]> = tris
            .split_whitespace()
            .map(|t| {
                let (j, k) = t.split_once(':').unwrap();
                [centre, u(j), u(k)]
            })
            .collect();
        let neighbours = if parts.len() == 4 {
            parts[2].split_whitespace().map(u).collect()
        } else {
            let mut nb: Vec<u64> = triangles.iter().flat_map(|t| [t[1], t[2]]).collect();
            nb.sort_unstable();
            nb.dedup();
            nb
        };
        out.push(Fan { centre, status: status(parts[1]), neighbours, triangles });
    }
    (set(vs), out)
}

#[derive(Debug)]
struct Expect {
    candidates: u64,
    kept3: u64,
    kept2: u64,
    facts: [u64; 6],
    triangles: Vec<[u64; 3]>,
    rejected: Vec<([u64; 3], u8, RejectReason)>,
    unused: Vec<(u64, FanStatus)>,
    loops: Option<Vec<Vec<u64>>>,
}

fn expect(l: &mut Lines<'_>) -> Expect {
    assert_eq!(l.next(), "expect");
    let candidates = u(l.field("candidates"));
    let kept3 = u(l.field("kept3"));
    let kept2 = u(l.field("kept2"));
    let fv: Vec<u64> = l.field("facts").split_whitespace().map(u).collect();
    let facts = [fv[0], fv[1], fv[2], fv[3], fv[4], fv[5]];
    let n = l.count("triangles");
    let triangles = (0..n)
        .map(|_| {
            let t: Vec<u64> = l.next().split_whitespace().map(u).collect();
            [t[0], t[1], t[2]]
        })
        .collect();
    let n = l.count("rejected");
    let rejected = (0..n)
        .map(|_| {
            let t: Vec<&str> = l.next().split_whitespace().collect();
            let tri = [u(t[0]), u(t[1]), u(t[2])];
            let votes: u8 = t[3].parse().unwrap();
            let reason = match t[4] {
                "single_vote" => RejectReason::SingleVote,
                "unorientable" => RejectReason::Unorientable,
                "edge_full" => RejectReason::EdgeFull { edge: [u(t[5]), u(t[6])] },
                "non_manifold" => RejectReason::NonManifold { edge: [u(t[5]), u(t[6])] },
                other => panic!("reason {other}"),
            };
            assert_eq!(reason.as_str(), t[4]);
            (tri, votes, reason)
        })
        .collect();
    let n = l.count("unused");
    let unused = (0..n)
        .map(|_| {
            let (s, st) = l.next().split_once(' ').unwrap();
            (u(s), status(st))
        })
        .collect();
    let loops = l.0.peek().is_some().then(|| {
        let n = l.count("loops");
        (0..n).map(|_| l.next().split_whitespace().map(u).collect()).collect()
    });
    Expect { candidates, kept3, kept2, facts, triangles, rejected, unused, loops }
}

/// The boundary loops of a mesh as vertex sources, walked along the winding from the smallest
/// source (test-side, independent of the crate).
fn loops(s: &Stitched) -> Vec<Vec<u64>> {
    let tris: Vec<[u64; 3]> = s.mesh.triangles().collect();
    let mut count: BTreeMap<(u64, u64), u32> = BTreeMap::new();
    for t in &tris {
        for (a, b) in [(t[0], t[1]), (t[1], t[2]), (t[2], t[0])] {
            *count.entry((a.min(b), a.max(b))).or_default() += 1;
        }
    }
    let mut next: BTreeMap<u64, u64> = BTreeMap::new();
    for t in &tris {
        for (a, b) in [(t[0], t[1]), (t[1], t[2]), (t[2], t[0])] {
            if count[&(a.min(b), a.max(b))] == 1 {
                assert!(next.insert(a, b).is_none(), "two outgoing boundary edges at {a}");
            }
        }
    }
    let src = &s.report.vertex_sources;
    let mut out = Vec::new();
    while let Some(start) = next.keys().next().copied() {
        let mut lp = vec![src[start as usize]];
        let mut x = next.remove(&start).unwrap();
        while x != start {
            lp.push(src[x as usize]);
            x = next.remove(&x).unwrap();
        }
        out.push(lp);
    }
    out
}

fn compare(case: &str, got: &Stitched, e: &Expect, vs: &VertexSet) {
    let r = &got.report;
    let mut sources: Vec<u64> = vs.vertices.iter().map(|v| v.source).collect();
    sources.sort_unstable();
    assert_eq!(r.vertex_sources, sources, "{case}: vertex numbering");
    assert_eq!(got.mesh.vertex_count(), sources.len() as u64);
    // Positions and normals copied bit for bit, in source order.
    let by: BTreeMap<u64, &PrepVertex> = vs.vertices.iter().map(|v| (v.source, v)).collect();
    let normals = got.mesh.vertex_attrs().normal.as_ref().unwrap();
    for (i, s) in sources.iter().enumerate() {
        let p = got.mesh.vertex(i as u64).unwrap();
        assert_eq!(p.map(f64::to_bits), by[s].position.map(f64::to_bits), "{case}: vertex {s}");
        let n = [normals[0][i], normals[1][i], normals[2][i]];
        assert_eq!(n.map(f64::to_bits), by[s].normal.map(f64::to_bits), "{case}: normal {s}");
    }
    assert_eq!(r.candidates, e.candidates, "{case}: candidates");
    assert_eq!(r.kept_three_vote, e.kept3, "{case}: kept3");
    assert_eq!(r.kept_two_vote, e.kept2, "{case}: kept2");
    let tris: Vec<[u64; 3]> = got.mesh.triangles().collect();
    assert_eq!(tris, e.triangles, "{case}: triangles");
    let rej: Vec<([u64; 3], u8, RejectReason)> = r.rejected.iter().map(|x| (x.triangle, x.votes, x.reason)).collect();
    assert_eq!(rej, e.rejected, "{case}: rejected");
    let unused: Vec<(u64, FanStatus)> = r.unused.iter().map(|x| (x.source, x.fan)).collect();
    assert_eq!(unused, e.unused, "{case}: unused");
    assert_eq!(r.candidates, r.kept_three_vote + r.kept_two_vote + r.rejected.len() as u64);
    let ft = got.mesh.facts();
    let facts = [
        ft.boundary_edges,
        ft.nonmanifold_edges,
        ft.misoriented_pairs,
        ft.components,
        u64::from(ft.closed),
        u64::from(ft.oriented),
    ];
    assert_eq!(facts, e.facts, "{case}: facts");
    assert_eq!(ft.nonmanifold_edges, 0, "{case}: REQ-002");
    if let Some(l) = &e.loops {
        assert_eq!(&loops(got), l, "{case}: boundary loops");
    }
}

const FAN_CASES: [&str; 7] =
    ["hex_grid", "hex_grid_wide", "square_grid", "square_grid_tilted", "two_patches_gap", "jitter_dense", "status_mix"];

/// A FAN fixture's vertex set and reference fans, and its STITCH expectation.
fn fan_case(case: &str) -> (VertexSet, Vec<Fan>, Expect) {
    let text = read(&format!("{case}.fan.txt"));
    let mut l = Lines::new(&text);
    assert_eq!(l.field("case"), case);
    let _g = l.field("g");
    let (vs, fans) = vertices_and_fans(&mut l);
    let st = read(&format!("{case}.stitch.txt"));
    let mut m = Lines::new(&st);
    assert_eq!(m.field("case"), case);
    assert_eq!(m.field("from"), format!("{case}.fan.txt"));
    (vs, fans, expect(&mut m))
}

/// A self-contained STITCH fixture: vertices, fans and expectation (and `g` if present).
fn own_case(case: &str) -> (Option<f64>, VertexSet, Vec<Fan>, Expect) {
    let text = read(&format!("{case}.stitch.txt"));
    let mut l = Lines::new(&text);
    assert_eq!(l.field("case"), case);
    let g = if l.0.peek().unwrap().starts_with("g ") { Some(f(l.field("g"))) } else { None };
    let (vs, fans) = vertices_and_fans(&mut l);
    let e = expect(&mut l);
    (g, vs, fans, e)
}

#[test]
fn fan_fixtures_stitch_as_the_reference() {
    for case in FAN_CASES {
        let (vs, ref_fans, e) = fan_case(case);
        let got = stitch(&ref_fans, &vs, FRAME).unwrap();
        compare(case, &got, &e, &vs);
    }
}

#[test]
fn every_rule_on_hand_built_fans() {
    let (_, vs, fans, e) = own_case("votes_mix");
    let got = stitch(&fans, &vs, FRAME).unwrap();
    compare("votes_mix", &got, &e, &vs);
    // Every reason occurs, and a two-vote triangle was both accepted and refused.
    let reasons: Vec<&str> = got.report.rejected.iter().map(|r| r.reason.as_str()).collect();
    for want in ["single_vote", "unorientable", "edge_full", "non_manifold"] {
        assert!(reasons.contains(&want), "{want}");
    }
    assert!(got.report.kept_two_vote > 0);
}

#[test]
fn ac2_a_slot_wider_than_g_stays_one_boundary_loop() {
    let (g, vs, ref_fans, e) = own_case("plate_gap");
    let g = g.unwrap();
    // The crate's FAN agrees with the reference fans (the file lists no neighbour order).
    let got_fans = fans(&vs, g, 1).unwrap();
    let key = |f: &[Fan]| f.iter().map(|x| (x.centre, x.status, x.triangles.clone())).collect::<Vec<_>>();
    assert_eq!(key(&got_fans), key(&ref_fans));
    let got = stitch(&got_fans, &vs, FRAME).unwrap();
    compare("plate_gap", &got, &e, &vs);
    // Two loops: the plate's outline and the slot (fixture comment names the slot's start).
    let lp = loops(&got);
    assert_eq!(lp.len(), 2);
    assert_eq!(got.mesh.facts().components, 1);
}

fn plate_cloud(vs: &VertexSet) -> PointCloud {
    // Sources are point indices in file order.
    let mut v: Vec<&PrepVertex> = vs.vertices.iter().collect();
    v.sort_by_key(|p| p.source);
    for (i, p) in v.iter().enumerate() {
        assert_eq!(p.source, i as u64);
    }
    let pts: Vec<[f64; 3]> = v.iter().map(|p| p.position).collect();
    let attrs = AttributeSet {
        normal: Some([
            v.iter().map(|p| p.normal[0]).collect(),
            v.iter().map(|p| p.normal[1]).collect(),
            v.iter().map(|p| p.normal[2]).collect(),
        ]),
        ..AttributeSet::default()
    };
    PointCloud::new(FRAME, PointBuffer::from_points(&pts), attrs).unwrap()
}

#[test]
fn reconstruct_in_memory_is_prep_fan_stitch() {
    let (g, vs, _, e) = own_case("plate_gap");
    let g = g.unwrap();
    let cloud = plate_cloud(&vs);
    let valid = vec![true; vs.vertices.len()];
    // h = 0.25 mm: every point is alone in its cell (the reference checks the spacing), so
    // PREP keeps every point unmoved with its own index as source.
    for threads in [1, 3] {
        let mut prep = PrepParams::new(0.25e-3);
        prep.threads = threads;
        let got = reconstruct_in_memory(&cloud, &valid, &ReconParams { prep, g }).unwrap();
        compare("plate_gap via reconstruct_in_memory", &got, &e, &vs);
        assert_eq!(got.mesh.frame(), FRAME);
        assert_eq!(got.report.moved_vertices, 0);
        assert!(got.report.vertex_status.iter().all(|s| *s == VertexStatus::Unmoved));
    }
    // A bad gap is refused before any work.
    let bad = ReconParams { prep: PrepParams::new(0.25e-3), g: f64::NAN };
    assert_eq!(
        reconstruct_in_memory(&cloud, &valid, &bad).unwrap_err(),
        PolyError::InvalidParameter { name: "g", reason: "not a finite value in [2^-100, 2^100] m" }
    );
}

/// A deterministic shuffle (splitmix64), test-side.
fn shuffled<T: Clone>(items: &[T], seed: u64) -> Vec<T> {
    let mut s = seed;
    let mut next = || {
        s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = s;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    };
    let mut v = items.to_vec();
    for i in (1..v.len()).rev() {
        let j = (next() % (i as u64 + 1)) as usize;
        v.swap(i, j);
    }
    v
}

#[test]
fn ac3_fan_and_vertex_order_do_not_matter() {
    let mut all: Vec<(String, VertexSet, Vec<Fan>)> = Vec::new();
    for case in FAN_CASES {
        let (vs, f, _) = fan_case(case);
        all.push((case.to_string(), vs, f));
    }
    for case in ["votes_mix", "plate_gap"] {
        let (_, vs, f, _) = own_case(case);
        all.push((case.to_string(), vs, f));
    }
    for (case, vs, f) in &all {
        let base = stitch(f, vs, FRAME).unwrap();
        let d = digest_mesh(&base.mesh);
        let mut rev = f.clone();
        rev.reverse();
        let mut triangles_rev = f.clone();
        for fan in &mut triangles_rev {
            fan.triangles.reverse();
        }
        let vs_shuffled = set(shuffled(&vs.vertices, 11));
        for (what, fans_v, vs_v) in [
            ("reversed fans", rev, vs.clone()),
            ("shuffled fans", shuffled(f, 5), vs.clone()),
            ("reversed fan triangles", triangles_rev, vs.clone()),
            ("shuffled vertices", f.clone(), vs_shuffled),
        ] {
            let got = stitch(&fans_v, &vs_v, FRAME).unwrap();
            assert_eq!(digest_mesh(&got.mesh), d, "{case}: {what}");
            assert_eq!(got, base, "{case}: {what}");
        }
    }
}

// ---------------------------------------------------------------- AC-1: the sphere

struct Sphere {
    radius: f64,
    g: f64,
    vs: VertexSet,
}

fn sphere() -> Sphere {
    let text = read("sphere_points.txt");
    let mut l = Lines::new(&text);
    assert_eq!(l.field("case"), "sphere_points");
    let radius = f(l.field("radius"));
    let n = l.count("points");
    let (cc, ss) = (f(l.field("rot_cos")), f(l.field("rot_sin")));
    let g = f(l.field("g"));
    let nf = n as f64;
    let (mut c, mut s) = (1.0f64, 0.0f64);
    let mut vertices = Vec::with_capacity(n);
    for i in 0..n {
        let z = 1.0 - (2.0 * i as f64 + 1.0) / nf;
        let r = (1.0 - z * z).sqrt();
        let q = [r * c, r * s, z];
        let len = ((q[0] * q[0] + q[1] * q[1]) + q[2] * q[2]).sqrt();
        let nn = [q[0] / len, q[1] / len, q[2] / len];
        vertices.push(vertex(i as u64, [radius * nn[0], radius * nn[1], radius * nn[2]], nn));
        (c, s) = (c * cc - s * ss, s * cc + c * ss);
    }
    // The reference's samples, bit for bit.
    let k = l.count("samples");
    assert!(k > 100);
    for _ in 0..k {
        let t: Vec<&str> = l.next().split_whitespace().collect();
        let v = &vertices[t[0].parse::<usize>().unwrap()];
        assert_eq!(v.position.map(f64::to_bits), [f(t[1]), f(t[2]), f(t[3])].map(f64::to_bits), "sample {}", t[0]);
        assert_eq!(v.normal.map(f64::to_bits), [f(t[4]), f(t[5]), f(t[6])].map(f64::to_bits), "sample {}", t[0]);
    }
    Sphere { radius, g, vs: set(vertices) }
}

// wasm32-wasip1 has no threads, and the 125 664 fans single-threaded under the interpreter take
// many minutes; the test runs natively on Linux, Windows and macOS.
#[test]
#[cfg_attr(target_family = "wasm", ignore = "no threads on wasm32-wasip1; runs natively on three OSes")]
fn ac1_sphere_is_closed_manifold_and_outward_and_ac3_on_it() {
    let sp = sphere();
    assert_eq!(sp.radius, 0.05);
    assert_eq!(sp.vs.vertices.len(), 125_664);
    let threads = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1).clamp(1, 8);
    let fs = fans(&sp.vs, sp.g, threads).unwrap();
    let got = stitch(&fs, &sp.vs, FRAME).unwrap();
    let m: &Mesh = &got.mesh;
    let ft = m.facts();
    assert!(ft.closed, "{ft:?}; rejected {}", got.report.rejected.len());
    assert_eq!(ft.nonmanifold_edges, 0);
    assert_eq!(ft.boundary_edges, 0);
    assert!(ft.oriented);
    assert_eq!(ft.components, 1);
    // Every face normal points outward (the sphere is centred at the origin).
    for t in m.triangles() {
        let [a, b, c] = t.map(|i| m.vertex(i).unwrap());
        let (u, w) = ([b[0] - a[0], b[1] - a[1], b[2] - a[2]], [c[0] - a[0], c[1] - a[1], c[2] - a[2]]);
        let n = [u[1] * w[2] - u[2] * w[1], u[2] * w[0] - u[0] * w[2], u[0] * w[1] - u[1] * w[0]];
        let centroid = [a[0] + b[0] + c[0], a[1] + b[1] + c[1], a[2] + b[2] + c[2]];
        assert!(n[0] * centroid[0] + n[1] * centroid[1] + n[2] * centroid[2] > 0.0, "inward triangle {t:?}");
    }
    // Euler characteristic over the used vertices: V - E + F = 2 (E = 3F/2 when closed).
    let used = m.vertex_count() - got.report.unused.len() as u64;
    let faces = m.triangle_count();
    assert_eq!(faces % 2, 0);
    assert_eq!(used as i64 - (3 * faces / 2) as i64 + faces as i64, 2);
    // AC-3: the fans in reverse order give the same digest.
    let mut rev = fs.clone();
    rev.reverse();
    let again = stitch(&rev, &sp.vs, FRAME).unwrap();
    assert_eq!(digest_mesh(&again.mesh), digest_mesh(m));
    assert_eq!(again, got);
}

// ---------------------------------------------------------------- errors and reports

fn tri_set() -> (VertexSet, Vec<Fan>) {
    let z = [0.0, 0.0, 1.0];
    let vs = set(vec![vertex(4, [0.0; 3], z), vertex(9, [1.0, 0.0, 0.0], z), vertex(2, [0.0, 1.0, 0.0], z)]);
    let fan = |c: u64, j: u64, k: u64| Fan {
        centre: c,
        status: FanStatus::Ok,
        neighbours: vec![j, k],
        triangles: vec![[c, j, k]],
    };
    (vs, vec![fan(4, 9, 2), fan(9, 2, 4), fan(2, 4, 9)])
}

fn refused(fans: &[Fan], vs: &VertexSet) -> &'static str {
    match stitch(fans, vs, FRAME) {
        Err(PolyError::InvalidParameter { name, .. }) => name,
        other => panic!("not refused: {other:?}"),
    }
}

#[test]
fn one_triangle_is_wound_by_its_normals() {
    let (vs, fs) = tri_set();
    let got = stitch(&fs, &vs, FRAME).unwrap();
    // Sources 2, 4, 9 are mesh vertices 0, 1, 2; normal +z: (4, 9, 2) is ccw about +z.
    assert_eq!(got.report.vertex_sources, vec![2, 4, 9]);
    assert_eq!(got.mesh.triangles().collect::<Vec<_>>(), vec![[0, 1, 2]]);
    let mut down = vs.clone();
    for v in &mut down.vertices {
        v.normal = [0.0, 0.0, -1.0];
    }
    let got = stitch(&fs, &down, FRAME).unwrap();
    assert_eq!(got.mesh.triangles().collect::<Vec<_>>(), vec![[0, 2, 1]]);
}

#[test]
fn bad_inputs_are_refused_in_order() {
    let (vs, fs) = tri_set();
    let mut v = vs.clone();
    v.vertices[1].position[0] = f64::INFINITY;
    v.vertices[2].normal = [0.0, 0.0, 2.0];
    assert_eq!(refused(&fs, &v), "vs.position");
    v.vertices[1].position[0] = 2f64.powi(501);
    assert_eq!(refused(&fs, &v), "vs.position");
    v.vertices[1].position[0] = 1.0;
    assert_eq!(refused(&fs, &v), "vs.normal");
    v.vertices[2].normal = [0.0, 0.0, 1.0];
    v.vertices[2].source = 4;
    assert_eq!(refused(&fs, &v), "vs.source");

    // Missing, extra, unknown or repeated centres.
    assert_eq!(refused(&fs[..2], &vs), "fans.centre");
    let mut extra = fs.clone();
    extra.push(fs[0].clone());
    assert_eq!(refused(&extra, &vs), "fans.centre");
    let mut unknown = fs.clone();
    unknown[1].centre = 77;
    assert_eq!(refused(&unknown, &vs), "fans.centre");
    // Status and triangles disagree.
    let mut st = fs.clone();
    st[0].status = FanStatus::AllEdgesLong;
    assert_eq!(refused(&st, &vs), "fans.status");
    let mut st = fs.clone();
    st[0].triangles.clear();
    assert_eq!(refused(&st, &vs), "fans.status");
    // Malformed triangles.
    for bad in [[9, 4, 2], [4, 4, 2], [4, 9, 77]] {
        let mut t = fs.clone();
        t[0].triangles = vec![bad];
        assert_eq!(refused(&t, &vs), "fans.triangles", "{bad:?}");
    }
    let mut twice = fs.clone();
    twice[0].triangles = vec![[4, 9, 2], [4, 2, 9]];
    assert_eq!(refused(&twice, &vs), "fans.triangles");
}

#[test]
fn no_kept_triangle_is_an_empty_mesh_error() {
    let (vs, mut fs) = tri_set();
    // Only one fan proposes the triangle: a single vote.
    fs[1].triangles.clear();
    fs[1].status = FanStatus::NoNeighbours;
    fs[2].triangles.clear();
    fs[2].status = FanStatus::AllEdgesLong;
    let e = stitch(&fs, &vs, FRAME).unwrap_err();
    assert_eq!(e, PolyError::EmptyMesh { candidates: 1, ok_fans: 1 });
    assert_eq!(e.code(), "scan.poly.empty_mesh");
    assert_eq!(e.to_string(), "scan.poly.empty_mesh: no triangle kept (1 candidates, 1 ok fans)");
    // An empty vertex set.
    assert_eq!(stitch(&[], &set(vec![]), FRAME).unwrap_err(), PolyError::EmptyMesh { candidates: 0, ok_fans: 0 });
    // A collinear triangle with three votes is unorientable, so nothing is kept either.
    let (mut vs, fs) = tri_set();
    vs.vertices[2].position = [2.0, 0.0, 0.0];
    assert_eq!(stitch(&fs, &vs, FRAME).unwrap_err(), PolyError::EmptyMesh { candidates: 1, ok_fans: 3 });
}

#[test]
fn moved_vertices_are_reported_as_computed() {
    // D-045: a smoothed position is not a measured point; the report says which vertices moved.
    let (mut vs, fs) = tri_set();
    vs.vertices[1].status = VertexStatus::Smoothed;
    vs.vertices[1].displacement_m = 1e-6;
    vs.smoothing = true;
    let got = stitch(&fs, &vs, FRAME).unwrap();
    assert_eq!(got.report.moved_vertices, 1);
    // Source 9 is mesh vertex 2.
    assert_eq!(got.report.vertex_status, vec![VertexStatus::Unmoved, VertexStatus::Unmoved, VertexStatus::Smoothed]);
    assert!(got.report.vertex_status[2].moved());
}
